'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const {defaults,status,latest}=FarmaLogic,KEY='farmanexo-v1';
let branches=[],catalog=[],isbmIndex={ids:[],record_count:124,code_count:121},data={version:1,verifications:[],medications:[],settings:{...defaults}},view='overview',page=1,medPage=1,catalogGroup='phase1',map,markers,filter={q:'',department:'',chain:'',medication:'',status:'',branchstatus:'ACTIVO'},latestRecords=[];
const titles={overview:['Cada consulta cuenta.','Una vista clara de tus verificaciones, sucursales y próximos pasos.','Panorama general'],branches:['Cerca de cada sucursal.','Directorio de farmacias, contacto y seguimiento de disponibilidad.','Sucursales'],isbm:['Medicamentos ISBM','Catálogo exclusivo ISBM: códigos, composición, presentación y unidad de medida.','Medicamentos ISBM'],medications:['Medicamentos de fases 1 y 2','Catálogos separados del apartado ISBM.','Fases 1 y 2'],reviews:['La próxima consulta, a tiempo.','Prioriza las verificaciones vencidas y las existencias que necesitan revisión.','Por revisar'],history:['Cada verificación tiene historia.','Consulta cuándo, cómo y quién confirmó cada existencia.','Historial'],settings:['El seguimiento, a tu medida.','Configura tus plazos y administra los respaldos de este navegador.','Configuración']};
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',4500)}
let saving=false,sharedView=false;
function localData(){try{const o=JSON.parse(localStorage.getItem(KEY)||'null');if(validData(o))return o}catch{}return {version:1,verifications:[],medications:[],settings:{...defaults}}}
async function save(next=data){if(saving){toast('Hay un guardado en curso. Espera un momento.');return false}saving=true;try{if(FarmaSync.isTeamSession()){const saved=await FarmaSync.save(data,next);if(!validData(saved))throw Error('La respuesta compartida no tiene un formato válido.');data=saved;sharedView=true}else{localStorage.setItem(KEY,JSON.stringify(next));data=next}return true}catch(e){toast(e.message||'No se pudo guardar la información.');return false}finally{saving=false}}
function syncState(s){$('#teamButton').textContent=s.email?'Administración':'Opciones';const online=s.connected&&s.phase==='online';$('#storageStatus').innerHTML='<i></i>'+ (online?'Base de datos compartida':sharedView?'Equipo · conexión pendiente':'Datos en este navegador');$('#storageHint').textContent=online?'Cualquier persona puede actualizar existencias. Los cambios se comparten en tiempo real.':sharedView?'Mostrando la última consulta al servidor. Reconecta para guardar.':'Los registros locales se conservan; puedes copiarlos al equipo al conectar.';const banner=$('#syncBanner');banner.hidden=false;banner.classList.toggle('connected',online);banner.textContent=online?`Edición compartida abierta · Actualizado ${new Intl.DateTimeFormat('es-SV',{hour:'2-digit',minute:'2-digit',second:'2-digit'}).format(new Date(s.lastSync))}`:s.phase==='setup'?'Conexión preparada: falta activar las tablas en Supabase. Tus registros locales siguen guardados.':s.phase==='forbidden'?'Tu correo aún no tiene acceso al equipo. Un administrador debe autorizarlo.':s.phase==='loading'?'Conectando con los registros del equipo…':s.phase==='error'?`No se pudo conectar al equipo. ${s.error||''}`:'Conectando la edición compartida…';if(s.notice)banner.textContent+=' · '+s.notice;if(s.phase==='local'&&sharedView){data=localData();sharedView=false;refresh()}}
function syncData(next){if(!validData(next))throw Error('La base contiene registros con formato no válido. Contacta al administrador.');data=next;sharedView=true;const tag=document.activeElement?.tagName;if(!$('#dialog').open&&!['INPUT','SELECT','TEXTAREA'].includes(tag))refresh();else renderStats()}
function openTeam(){const state=FarmaSync.state(),local=localData();modal(modalHead('Datos compartidos','Todos pueden actualizar existencias sin iniciar sesión.')+`<div class="dialoginfo">${state.connected?'Conectado a la base compartida. Los cambios se muestran a todas las personas.':esc(state.error||'Conectando…')}</div><div class="importexport"><button class="btn secondary" id="retrySync">Actualizar conexión</button>${state.email?'<button class="btn secondary" id="signOutTeam">Salir de administración</button>':''}</div><h3 class="smallheading">REGISTROS ANTERIORES DE ESTE NAVEGADOR</h3><p class="hint">Hay ${local.verifications.length} verificaciones locales. Puedes copiarlas a la página compartida; los originales se conservan y los identificadores repetidos se omiten.</p><button class="btn primary" id="migrateLocal" ${state.connected?'':'disabled'}>Copiar verificaciones locales a la página</button>${state.role==='admin'?`<h3 class="smallheading">ADMINISTRACIÓN</h3><p class="hint">${esc(state.email)} · Administrador. Todas las personas pueden modificar existencias; estos accesos adicionales permiten administrar el catálogo y las reglas.</p><form id="memberForm"><div class="formgrid"><label class="field">Correo<input type="email" id="memberEmail" required maxlength="254"></label><label class="field">Permiso de administración<select id="memberRole"><option value="editor">Gestionar catálogo</option><option value="admin">Administrador</option><option value="blocked">Retirar permiso de administración</option></select></label></div><div class="formactions"><button class="btn primary" type="submit">Guardar permiso y crear enlace</button></div></form><div id="membersList"></div>`:`<details class="adminoptional"><summary>Administración (opcional)</summary><p class="hint">No necesitas entrar aquí para actualizar existencias. El acceso de administración permite cambiar reglas y gestionar el catálogo.</p><form id="teamLogin"><label class="field">Enlace personal de administración<textarea id="teamInvite" required rows="3" autocomplete="off" placeholder="Pega tu enlace de administración"></textarea></label><button class="btn secondary" id="acceptTeamInvite" type="submit">Entrar a administración</button></form></details>`}<p id="teamError" class="error" role="alert"></p><p class="hint">Cada actualización conserva su nombre, fecha y método de verificación. La contraseña se solicita únicamente para consultar ISBM.</p>`);if($('#teamLogin'))$('#teamLogin').onsubmit=async e=>{e.preventDefault();$('#acceptTeamInvite').disabled=true;try{await FarmaSync.acceptInvite($('#teamInvite').value);$('#teamInvite').value='';$('#dialog').close();refresh();toast('Administración habilitada.')}catch(err){$('#teamError').textContent=err.message}finally{if($('#acceptTeamInvite'))$('#acceptTeamInvite').disabled=false}};if($('#signOutTeam'))$('#signOutTeam').onclick=async()=>{try{await FarmaSync.signOut();$('#dialog').close();refresh();toast('Administración cerrada. La edición pública continúa disponible.')}catch(e){$('#teamError').textContent=e.message}};$('#retrySync').onclick=async()=>{await FarmaSync.retry();if($('#dialog').open){$('#dialog').close();openTeam()}};$('#migrateLocal').onclick=async()=>{const button=$('#migrateLocal');button.disabled=true;const merge=(a,b)=>[...new Map([...a,...b].map(x=>[x.id,x])).values()];const publicMeds=new Set(meds().map(m=>m.id));const records=local.verifications.filter(v=>publicMeds.has(v.medication_id)||isbmIndex.ids.includes(v.medication_id));if(records.length!==local.verifications.length&&!FarmaSync.canManageCatalog()){toast('Algunas consultas usan medicamentos locales adicionales. La administración debe agregarlos antes de copiarlas.');button.disabled=false;return}const next={...data,medications:FarmaSync.canManageCatalog()?merge(local.medications,data.medications):data.medications,verifications:merge(records,data.verifications)};if(await save(next)){ $('#dialog').close();refresh();toast('Verificaciones copiadas. Los originales locales se conservan.')}else if($('#migrateLocal'))button.disabled=false};if($('#memberForm')){loadMembers();$('#memberRole').onchange=()=>{$('#memberForm button[type="submit"]').textContent=$('#memberRole').value==='blocked'?'Retirar permiso':'Guardar permiso y crear enlace'};$('#memberForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type="submit"]');button.disabled=true;try{const email=$('#memberEmail').value,role=$('#memberRole').value;if(role==='blocked'){await FarmaSync.setMember(email,role);await loadMembers();toast('Permiso de administración retirado.')}else{const invite=await FarmaSync.issueInvite(email,role);$('#dialog').close();showInvite(invite)}}catch(err){$('#teamError').textContent=err.message}finally{button.disabled=false}}}}
function showInvite(invite){modal(modalHead('Enlace personal de acceso',invite.email)+`<div class="dialoginfo">Comparte este enlace únicamente con la persona indicada. Se utiliza una sola vez; crea otro para entrar en un dispositivo distinto o si ha caducado.</div><label class="field">Enlace de acceso<textarea id="issuedInvite" readonly rows="4" spellcheck="false">${esc(invite.link)}</textarea></label><div class="formactions"><button class="btn primary" id="copyInvite" type="button">Copiar enlace</button></div><p class="hint">Este acceso permite administrar reglas y catálogo; todas las personas pueden actualizar existencias sin usarlo.</p>`);$('#copyInvite').onclick=async()=>{try{await navigator.clipboard.writeText(invite.link);toast('Enlace copiado. Entrégalo a la persona indicada.')}catch{$('#issuedInvite').select();toast('Selecciona y copia el enlace.')}}}

async function loadMembers(){try{const members=await FarmaSync.members();if($('#membersList'))$('#membersList').innerHTML=members.map(m=>`<div class="historyitem"><strong>${esc(m.email)}</strong><p>${esc(({viewer:'Consulta',editor:'Editor',admin:'Administrador',blocked:'Bloqueado'})[m.role]||m.role)}</p></div>`).join('')}catch(e){if($('#teamError'))$('#teamError').textContent=e.message}}
function meds(){return [...catalog,...IsbmAccess.records(),...data.medications.filter(m=>medicationCollection(m)!=='isbm'||IsbmAccess.isUnlocked())]}
function protectedMedication(id){return isbmIndex.ids.includes(id)||data.medications.some(m=>m.id===id&&medicationCollection(m)==='isbm')}
function allKnownMedicationIds(){return new Set([...catalog.map(m=>m.id),...isbmIndex.ids])}
function medicationCollection(m){return m.collection||'unclassified'}
function catalogOptions(selected=''){return [['isbm','Medicamentos ISBM'],['phase1','Primera fase'],['phase2','Segunda fase'],['unclassified','Sin clasificar']].map(([key,label])=>{const rows=meds().filter(m=>medicationCollection(m)===key);if(key==='isbm'&&!IsbmAccess.isUnlocked())return '<optgroup label="ISBM · acceso protegido"><option disabled>Abre ISBM con contraseña para seleccionarlo</option></optgroup>';return rows.length?`<optgroup label="${label}">${rows.map(m=>`<option value="${esc(m.id)}" ${selected===m.id?'selected':''}>${esc(m.code||'Adicional')} · ${esc(m.name)}</option>`).join('')}</optgroup>`:''}).join('')}
function med(id){return meds().find(m=>m.id===id)||(protectedMedication(id)?{id,name:'Medicamento ISBM · acceso protegido',presentation:'Abre el apartado ISBM para ver detalles',unit:'unidades reportadas'}:undefined)}function branch(id){return branches.find(b=>b.id===id)}
function fmt(d,time=false){return new Intl.DateTimeFormat('es-SV',{dateStyle:'medium',...(time?{timeStyle:'short'}:{}),timeZone:'America/El_Salvador'}).format(new Date(d))}
function badge(s){return `<span class="badge ${s.color}">${s.label}</span>`}
function quantity(v){return !v?'—':v.availability==='out'?'Sin existencias':v.availability==='unknown'?'No confirmado':v.quantity===null?'Cantidad no informada':`${v.quantity} ${med(v.medication_id)?.unit||'unidades'}`}
function stock(v){return !v?'Sin consulta':v.availability==='out'?'Sin existencias':v.availability==='unknown'?'No confirmado':'Con existencias'}
function branchRecord(id){const rows=latestRecords.filter(v=>v.branch_id===id&&(!filter.medication||v.medication_id===filter.medication));return rows.sort((a,b)=>status(b,data.settings).rank-status(a,data.settings).rank||b.checked_at.localeCompare(a.checked_at))[0]}
function branchState(b){const v=branchRecord(b.id);return {...status(v,data.settings),record:v}}
function filtered(){const q=filter.q.toLocaleLowerCase();return branches.filter(b=>(!q||[b.name,b.id,b.address,b.district,b.municipality,b.department].some(s=>(s||'').toLocaleLowerCase().includes(q)))&&(!filter.department||b.department===filter.department)&&(!filter.chain||b.chain===filter.chain)&&(!filter.branchstatus||b.status===filter.branchstatus)&&(!filter.status||branchState(b).key===filter.status))}
function refresh(){latestRecords=latest(data.verifications);renderStats();$('#medCount').textContent=meds().filter(m=>medicationCollection(m)!=='isbm').length;$('#isbmCount').textContent=isbmIndex.record_count+data.medications.filter(m=>medicationCollection(m)==='isbm').length;$('#lockIsbm').hidden=!IsbmAccess.isUnlocked();$('#reviewCount').textContent=latestRecords.filter(v=>status(v,data.settings).rank>=2).length;if(['overview','branches'].includes(view))renderDirectory();if(view==='overview'){renderPriorities();renderMap()}if(['medications','isbm'].includes(view))renderMedications();if(view==='reviews')renderReviews();if(view==='history')renderHistory();if(view==='settings')renderSettings()}
function renderStats(){const states=latestRecords.map(v=>status(v,data.settings));$('#stats').innerHTML=[['Sucursales en el directorio',branches.length,`${branches.filter(b=>b.status==='ACTIVO').length} activas en la fuente`,'♧',''],['Verificaciones vigentes',states.filter(s=>s.key==='current').length,'Pares de sucursal y medicamento','✓','green'],['Recomendadas para revisión',states.filter(s=>s.key==='review').length,'Pocas unidades o plazo de aviso','◷','amber'],['Consultas urgentes',states.filter(s=>s.key==='urgent').length,'Necesitan una nueva verificación','↗','red']].map(([label,value,sub,icon,color])=>`<article class="stat ${color}"><div class="statlabel">${label}<span class="staticon">${icon}</span></div><div class="statvalue">${value}</div><small>${sub}</small></article>`).join('')}
function changeView(v){view=v;page=1;medPage=1;$('#title').textContent=titles[v][0];$('#subtitle').textContent=titles[v][1];$('#breadcrumb').textContent=titles[v][2];document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==v);document.querySelectorAll('#nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);b.setAttribute('aria-current',b.dataset.view===v?'page':'false')});$('#stats').hidden=['settings','medications','isbm','history'].includes(v);$('#notice').hidden=v!=='overview'||sessionStorage.getItem('notice-dismissed')==='1';refresh();if(v==='overview')setTimeout(()=>map?.invalidateSize(),50);window.scrollTo({top:0,behavior:'smooth'})}
function options(values,selected){return values.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}
function directoryMarkup(){return `<div class="filters"><label class="search"><span>⌕</span><input id="branchSearch" type="search" aria-label="Buscar sucursal" placeholder="Buscar sucursal, código o localidad…" value="${esc(filter.q)}"></label><select id="departmentFilter" aria-label="Departamento"><option value="">Todos los departamentos</option>${options([...new Set(branches.map(b=>b.department))].sort(),filter.department)}</select><select id="medicationFilter" aria-label="Medicamento"><option value="">Todos los medicamentos</option>${catalogOptions(filter.medication)}</select><select id="stateFilter" aria-label="Seguimiento"><option value="">Todo seguimiento</option>${[['unverified','Sin verificar'],['current','Vigente'],['review','En revisión'],['urgent','Consultar urgente']].map(([k,v])=>`<option value="${k}" ${filter.status===k?'selected':''}>${v}</option>`).join('')}</select><select id="chainFilter" aria-label="Cadena"><option value="">Todas las cadenas</option>${options([...new Set(branches.map(b=>b.chain))].sort(),filter.chain)}</select><select id="branchStatusFilter" aria-label="Estado de sucursal"><option value="">Cualquier estado de sucursal</option>${options(['ACTIVO','INACTIVO TEMPORAL','INACTIVO','RETIRADO'],filter.branchstatus)}</select><button class="rowbtn" id="resetFilters">Limpiar</button></div><div class="tablewrap"><table><thead><tr><th>Sucursal / ubicación</th><th>Disponibilidad reportada</th><th>Seguimiento</th><th>Última consulta</th><th>Acción</th></tr></thead><tbody id="directoryRows"></tbody></table><div class="empty" id="directoryEmpty" hidden><b>No encontramos sucursales</b><p>Prueba con otro término o limpia los filtros.</p></div></div><div class="pagination"><span id="directorySummary"></span><div><button class="rowbtn" id="prevPage" aria-label="Página anterior">←</button><span id="pageLabel"></span><button class="rowbtn" id="nextPage" aria-label="Página siguiente">→</button></div></div>`}
function renderDirectory(){(view==='overview'?$('#branches'):$('#directoryMount')).innerHTML='';const host=view==='overview'?$('#directoryMount'):$('#branches');host.innerHTML=directoryMarkup();bindFilters();renderRows()}
function bindFilters(){for(const [id,k] of [['departmentFilter','department'],['medicationFilter','medication'],['stateFilter','status'],['chainFilter','chain'],['branchStatusFilter','branchstatus']])$('#'+id).onchange=e=>{filter[k]=e.target.value;page=1;renderRows();if(view==='overview')renderMap()};$('#branchSearch').oninput=e=>{filter.q=e.target.value;page=1;renderRows();clearTimeout(bindFilters.t);bindFilters.t=setTimeout(()=>{if(view==='overview')renderMap()},200)};$('#resetFilters').onclick=()=>{filter={q:'',department:'',chain:'',medication:'',status:'',branchstatus:'ACTIVO'};page=1;renderDirectory();if(view==='overview')renderMap()};$('#prevPage').onclick=()=>{page--;renderRows()};$('#nextPage').onclick=()=>{page++;renderRows()}}
function renderRows(){const rows=filtered(),pages=Math.max(1,Math.ceil(rows.length/10));page=Math.min(pages,Math.max(1,page));$('#directoryRows').innerHTML=rows.slice((page-1)*10,page*10).map(b=>{const s=branchState(b),v=s.record;return `<tr><td><div class="branchname"><span class="branchicon">✚</span><div><strong>${esc(b.name)}</strong><small>${esc(b.district||b.municipality)} · ${esc(b.department)}</small><small>${esc(b.id)} · ${esc(b.chain)}${b.status!=='ACTIVO'?' · '+esc(b.status):''}</small></div></div></td><td><strong>${esc(stock(v))}</strong><small>${esc(v?quantity(v):'Pendiente de primera consulta')}</small>${v?`<small>${esc(med(v.medication_id)?.name)}</small>`:''}</td><td>${badge(s)}${v?`<small>${esc(s.reason)}</small>`:''}</td><td>${v?`${esc(fmt(v.checked_at))}<small>${esc(v.channel)}</small>`:'<span class="badge">Sin registro</span>'}</td><td><div class="actioncell"><button class="rowbtn" data-detail="${esc(b.id)}">Ver ficha</button><button class="rowbtn" data-verify="${esc(b.id)}" data-med="${esc(v?.medication_id||'')}" aria-label="Verificar ${esc(b.name)}">Actualizar</button></div></td></tr>`}).join('');$('#directoryEmpty').hidden=rows.length>0;$('#directorySummary').textContent=rows.length?`${(page-1)*10+1}–${Math.min(page*10,rows.length)} de ${rows.length} sucursales`:'0 sucursales';$('#pageLabel').textContent=`${page} / ${pages}`;$('#prevPage').disabled=page<=1;$('#nextPage').disabled=page>=pages}
function renderMap(){if(!window.L){$('#map').innerHTML='<div class="empty">No se pudo cargar el mapa. El directorio sigue disponible.</div>';return}if(!map){map=L.map('map',{scrollWheelZoom:false}).setView([13.78,-88.92],8);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',maxZoom:19}).addTo(map);markers=L.layerGroup().addTo(map)}markers.clearLayers();const mapped=filtered().filter(b=>Number.isFinite(b.lat)&&Number.isFinite(b.lng)&&b.lat>=13&&b.lat<=15&&b.lng>=-91&&b.lng<=-87);for(const b of mapped){const s=branchState(b);L.marker([b.lat,b.lng],{icon:L.divIcon({className:'marker '+s.color,iconSize:[11,11]})}).bindPopup(`<b>${esc(b.name)}</b><p>${esc(b.district||b.municipality)}<br>${esc(b.address)}</p>${badge(s)}<br><button class="rowbtn" data-detail="${esc(b.id)}">Ver sucursal →</button>`).addTo(markers)}$('#mapTotal').textContent=`${mapped.length} ubicadas`;renderMap.points=mapped;if(mapped.length&&filter.department)map.fitBounds(mapped.map(b=>[b.lat,b.lng]),{padding:[20,20],maxZoom:12})}
function renderPriorities(){const rows=latestRecords.filter(v=>status(v,data.settings).rank>=2).sort((a,b)=>status(b,data.settings).rank-status(a,data.settings).rank||a.checked_at.localeCompare(b.checked_at));$('#priorities').innerHTML=rows.length?rows.slice(0,3).map(v=>`<div class="priorityrow" data-detail="${esc(v.branch_id)}">${badge(status(v,data.settings))}<strong>${esc(branch(v.branch_id)?.name)}</strong><p>${esc(med(v.medication_id)?.name.slice(0,65))}</p></div>`).join(''):`<div class="emptypriority"><span>✓</span><b>Tu cola está al día</b><p>${data.verifications.length?'No hay verificaciones que requieran revisión.':'Registra tu primera consulta para comenzar a dar seguimiento.'}</p></div>`}
function renderIsbmGate(){ $('#isbm').innerHTML=`<section class="panel isbm-access"><div class="accessicon">▣</div><div class="eyebrow">ACCESO EXCLUSIVO</div><h2>Medicamentos ISBM</h2><p>Introduce la contraseña para consultar el catálogo ISBM integrado. El dashboard y las fases 1 y 2 siguen disponibles sin contraseña.</p><form id="isbmAccessForm"><label class="field">Contraseña ISBM<div class="passwordrow"><input id="isbmPassword" type="password" autocomplete="current-password" required><button class="rowbtn" type="button" id="showIsbmPassword" aria-pressed="false">Mostrar</button></div></label><p class="error" id="isbmError" role="alert"></p><button class="btn primary" type="submit" id="unlockIsbm">Entrar a ISBM →</button></form><p class="hint">El acceso a ISBM se cierra al recargar o pulsar «Bloquear ISBM».</p></section>`;$('#showIsbmPassword').onclick=e=>{const input=$('#isbmPassword'),show=input.type==='password';input.type=show?'text':'password';e.target.textContent=show?'Ocultar':'Mostrar';e.target.setAttribute('aria-pressed',String(show))};$('#isbmAccessForm').onsubmit=async e=>{e.preventDefault();const button=$('#unlockIsbm');button.disabled=true;$('#isbmError').textContent='';try{await IsbmAccess.unlock($('#isbmPassword').value);$('#isbmPassword').value='';refresh();toast('Acceso a ISBM habilitado en esta sesión.')}catch(err){$('#isbmError').textContent=err.message;button.disabled=false}}}
function lockIsbm(){IsbmAccess.lock();if(protectedMedication(filter.medication))filter.medication='';$('#dialog').close();$('#dialogBody').innerHTML='';map?.closePopup();for(const id of ['isbm','medications','history','reviews','branches','directoryMount'])$('#'+id).innerHTML='';refresh();toast('ISBM bloqueado. El dashboard continúa disponible.')}
function renderMedications(){const isIsbm=view==='isbm';if(isIsbm&&!IsbmAccess.isUnlocked()){renderIsbmGate();return}const old=$('#medSearch')?.value||'';$('#'+(isIsbm?'medications':'isbm')).innerHTML='';const groups=[['phase1','Primera fase'],['phase2','Segunda fase'],['unclassified','Sin clasificar']];const notice=isIsbm?`<b>ISBM integrado: ${isbmIndex.code_count} códigos y ${isbmIndex.record_count} registros de presentación.</b> Incluye los 119 registros de tarifas y los 109 complementarios; 104 coincidencias conciliadas y 3 variantes conservadas por diferencias de forma o envase.`:'<b>Primera fase: 162 registros · Segunda fase: 78 registros.</b> Importados de la hoja Medicamentos del archivo de tarifas. ISBM permanece separado.';$('#'+view).innerHTML=`<div class="catalogstats">${notice}</div>${isIsbm?'':`<div class="catalogtabs">${groups.map(([key,label])=>`<button class="btn ${catalogGroup===key?'primary':'secondary'}" data-catalog-group="${key}">${label} <span>${meds().filter(m=>medicationCollection(m)===key).length}</span></button>`).join('')}</div>`}<div class="cataloghead"><p>${isIsbm?'Las variaciones de nombre se conservan como referencia. Las diferencias de presentación se señalan para confirmar.':'La fase asignada en el archivo se conserva. El estado del catálogo no indica existencias en una sucursal.'}</p><div class="importexport">${isIsbm?'<button class="btn secondary" id="showReconciliation">Ver conciliación</button>':''}<button class="btn secondary" id="addMed">＋ Agregar medicamento</button></div></div><div class="filters"><label class="search"><span>⌕</span><input id="medSearch" type="search" placeholder="Buscar por nombre, código, descripción alternativa o presentación…" aria-label="Buscar medicamento" value="${esc(old)}"></label><span class="sourcebadge">${isIsbm?'ISBM · tarifas + complemento 109':'Tarifas · Medicamentos'}</span></div><div class="tablewrap"><table><thead><tr><th>Código / origen</th><th>Medicamento</th><th>Composición</th><th>Presentación / unidad</th><th>Estado en fuente</th><th>Tarifa rollout con IVA</th></tr></thead><tbody id="medRows"></tbody></table><div class="empty" id="medEmpty" hidden><b>Sin medicamentos en esta selección</b><p>Prueba con otro término o selecciona otro apartado.</p></div></div><div class="pagination"><span id="medSummary"></span><div><button class="rowbtn" id="medPrev">←</button><span id="medPage"></span><button class="rowbtn" id="medNext">→</button></div></div><p class="hint">Fuentes: archivo de tarifas, hoja Medicamentos${isIsbm?', y complemento 109 Medicamentos ISBM.xlsx':''}. Tarifas referenciales del archivo; los valores ausentes no se convierten a cero. La presentación comercial y las existencias se confirman con cada sucursal.</p>`;$('#medSearch').oninput=()=>{medPage=1;medRows()};$('#medPrev').onclick=()=>{medPage--;medRows()};$('#medNext').onclick=()=>{medPage++;medRows()};$('#addMed').hidden=FarmaSync.isTeamSession()&&!FarmaSync.canManageCatalog();$('#addMed').onclick=()=>addMedication(isIsbm?'isbm':catalogGroup);if(isIsbm)$('#showReconciliation').onclick=showReconciliation;document.querySelectorAll('[data-catalog-group]').forEach(b=>b.onclick=()=>{catalogGroup=b.dataset.catalogGroup;medPage=1;$('#medSearch').value='';renderMedications()});medRows()}
function medRows(){const group=view==='isbm'?'isbm':catalogGroup,q=$('#medSearch').value.toLowerCase(),rows=meds().filter(m=>medicationCollection(m)===group&&JSON.stringify(m).toLowerCase().includes(q)),pages=Math.max(1,Math.ceil(rows.length/12));medPage=Math.min(pages,Math.max(1,medPage));$('#medRows').innerHTML=rows.slice((medPage-1)*12,medPage*12).map(m=>`<tr><td><strong>${esc(m.code||'Adicional')}</strong><small>${m.number?'Complemento n.º '+m.number:'Tarifas'}</small><small>${esc((m.sources||['Personalizado']).join(' + '))}</small></td><td class="catalogname"><strong>${esc(m.name)}</strong>${(m.aliases||[]).map(a=>`<small>También en fuente: ${esc(a)}</small>`).join('')}${m.review_note?`<small class="variantnote">⚠ ${esc(m.review_note)}</small>`:''}</td><td>${esc(m.composition||'No desglosada')}</td><td>${esc(m.presentation)}<small>Tipo: ${esc(m.type||'No informado')}</small><small>U/M: ${esc(m.unit||'unidades')}</small></td><td>${esc(m.state||'No informado')}<small>${esc(m.agreement||'')}</small></td><td>${typeof m.price_rollout_iva==='number'?new Intl.NumberFormat('es-SV',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:6}).format(m.price_rollout_iva):'No informada'}</td></tr>`).join('');$('#medEmpty').hidden=rows.length>0;$('#medSummary').textContent=`${rows.length} registros · ${rows.length?((medPage-1)*12+1):0}–${Math.min(medPage*12,rows.length)}`;$('#medPage').textContent=`${medPage} / ${pages}`;$('#medPrev').disabled=medPage<=1;$('#medNext').disabled=medPage>=pages}
function showReconciliation(){if(!IsbmAccess.isUnlocked())return;const audit=IsbmAccess.audit();modal(modalHead('Conciliación ISBM','Se conserva la trazabilidad de ambas fuentes.')+`<div class="dialoginfo">119 registros de tarifas + 109 del complemento − 104 coincidencias consolidadas = 124 registros de presentación, correspondientes a 121 códigos.</div><p class="hint">Dos coincidencias solo diferían por ceros iniciales (169/00000169 y 174/00000174). Se preservaron los identificadores antiguos para conservar tus verificaciones. Amiodarona y letrozol aparecen también en segunda fase en la fuente de tarifas; sus registros ISBM provienen del complemento y permanecen independientes.</p><h3 class="smallheading">DIFERENCIAS QUE SE MANTIENEN SEPARADAS</h3>${audit.separate_variants.map(v=>`<div class="historyitem"><strong>${esc(v.code)}</strong><p>${esc(v.note)}</p></div>`).join('')}<p class="hint">No se infiere equivalencia clínica por semejanza del nombre. La forma, vía, concentración y envase deben confirmarse durante la consulta.</p>`)}
function verificationTable(rows,history=false){return rows.length?`<div class="tablewrap" style="border-top:1px solid var(--line);border-radius:8px"><table><thead><tr><th>Sucursal / medicamento</th><th>Existencias</th><th>${history?'Consulta registrada':'Seguimiento actual'}</th><th>Fecha / canal</th><th>Acción</th></tr></thead><tbody>${rows.map(v=>`<tr><td><strong>${esc(branch(v.branch_id)?.name||v.branch_id)}</strong><small>${esc(med(v.medication_id)?.name||v.medication_id)}</small><small>Comercial: ${esc(v.commercial||'No informada')}</small></td><td>${esc(quantity(v))}</td><td>${history?`<strong>${esc(stock(v))}</strong><small>${esc(v.verifier)}</small>`:badge(status(v,data.settings))}<small>${esc(history?v.notes:status(v,data.settings).reason)}</small></td><td>${esc(fmt(v.checked_at,true))}<small>${esc(v.channel)} · ${esc(v.verifier)}</small>${v.author_email?`<small>Registrado por: ${esc(v.author_email)}</small>`:''}</td><td><button class="rowbtn" data-verify="${esc(v.branch_id)}" data-med="${esc(v.medication_id)}">Consultar otra vez</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="panel empty"><b>${history?'Todavía no hay consultas registradas':'Sin consultas pendientes'}</b><p>${history?'Registra una verificación para comenzar el historial.':'Las verificaciones que necesiten seguimiento aparecerán aquí.'}</p></div>`}
function renderReviews(){const rows=latestRecords.filter(v=>status(v,data.settings).rank>=2).sort((a,b)=>status(b,data.settings).rank-status(a,data.settings).rank||a.checked_at.localeCompare(b.checked_at));$('#reviews').innerHTML=`<div class="cataloghead"><p>${rows.length} pares de sucursal y medicamento requieren seguimiento.</p></div>`+verificationTable(rows)}
function renderHistory(){const rows=[...data.verifications].sort((a,b)=>b.checked_at.localeCompare(a.checked_at)||(b.received_at||b.created_at).localeCompare(a.received_at||a.created_at)||b.created_at.localeCompare(a.created_at));$('#history').innerHTML=`<div class="cataloghead"><p>${rows.length} verificaciones guardadas · Las consultas nuevas conservan las anteriores.</p></div>`+verificationTable(rows,true)}
function modal(html){$('#dialogBody').innerHTML=html;$('#dialog').showModal();$('#dialog').querySelector('.close').onclick=()=>$('#dialog').close()}
function modalHead(title,sub=''){return `<div class="dialoghead"><div><h2>${title}</h2><p>${sub}</p></div><button class="close" aria-label="Cerrar">×</button></div>`}
function localDateValue(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function verify(branchId='',medId=''){if(!IsbmAccess.isUnlocked()&&protectedMedication(medId||filter.medication)){changeView('isbm');toast('Introduce la contraseña de ISBM para verificar ese medicamento.');return}const selected=branch(branchId);modal(modalHead('Registrar verificación','Confirma existencias y deja un registro de la consulta.')+`<form id="verifyForm"><div class="formgrid"><label class="field full">Buscar sucursal<input id="verifySearch" type="search" placeholder="Filtrar por nombre o código…" aria-label="Filtrar sucursales"></label><label class="field full">Sucursal<select name="branch_id" id="verifyBranch" required>${'<option value="">Selecciona una sucursal</option>'+branches.map(b=>`<option value="${esc(b.id)}" ${b.id===branchId?'selected':''}>${esc(b.name)} · ${esc(b.id)}${b.status==='ACTIVO'?'':' · '+esc(b.status)}</option>`).join('')}</select></label><label class="field full">Medicamento<select name="medication_id" id="verifyMed" required><option value="">Selecciona un medicamento</option>${catalogOptions(medId||filter.medication)}</select></label><div class="dialoginfo full" id="medInfo">Selecciona un medicamento para ver la presentación del catálogo.</div><label class="field">Disponibilidad reportada<select name="availability" id="verifyAvailability"><option value="available">Con existencias</option><option value="out">Sin existencias</option><option value="unknown">No se pudo confirmar</option></select></label><label class="field">Cantidad <span id="unitLabel">en la unidad del catálogo</span><input type="number" name="quantity" id="verifyQuantity" min="1" max="1000000" step="1" placeholder="Vacío si no informaron cantidad"><small>No confundas tabletas con cajas. Usa la U/M indicada.</small></label><label class="field full">Marca y presentación comercial reportada<input name="commercial" id="verifyCommercial" maxlength="500" placeholder="Ej. marca, concentración, caja de 30 tabletas" required><small>Se guarda tal como la confirma la sucursal, sin sustituir la presentación del catálogo.</small></label><label class="field">Canal de verificación<select name="channel" required>${options(['Llamada','WhatsApp','NERD','Otro'],'Llamada')}</select></label><label class="field">Fecha y hora de consulta<input name="checked_at" id="verifyDate" type="datetime-local" required value="${localDateValue()}" max="${localDateValue()}"><small>Hora local de tu dispositivo. Reportes en hora de El Salvador.</small></label><label class="field full">Verificado por<input name="verifier" required maxlength="120" placeholder="Nombre o iniciales" value="${esc(FarmaSync.state().email||'')}"></label><label class="field full">Notas<textarea name="notes" rows="2" maxlength="2000" placeholder="Observaciones o referencia de la consulta"></textarea></label></div><p class="error" id="formError" role="alert"></p><div class="formactions"><button class="btn secondary" type="button" id="cancelVerify">Cancelar</button><button class="btn primary" type="submit">Guardar verificación</button></div></form>`);$('#cancelVerify').onclick=()=>$('#dialog').close();$('#verifySearch').oninput=e=>{const q=e.target.value.toLowerCase(),select=$('#verifyBranch'),current=select.value;select.innerHTML='<option value="">Selecciona una sucursal</option>'+branches.filter(b=>b.name.toLowerCase().includes(q)||b.id.toLowerCase().includes(q)).map(b=>`<option value="${esc(b.id)}" ${b.id===current?'selected':''}>${esc(b.name)} · ${esc(b.id)} · ${esc(b.status)}</option>`).join('')};$('#verifyMed').onchange=()=>{const m=med($('#verifyMed').value);$('#medInfo').textContent=m?`Catálogo: ${m.presentation} · Composición: ${m.composition||'No especificada'} · U/M: ${m.unit||'unidades'}`:'Selecciona un medicamento.';$('#unitLabel').textContent=m?`en ${m.unit||'unidades'}`:'en la unidad del catálogo'};$('#verifyMed').onchange();$('#verifyAvailability').onchange=e=>{const a=e.target.value;$('#verifyQuantity').disabled=a!=='available';$('#verifyQuantity').value='';$('#verifyCommercial').required=a==='available'};const fillCurrent=()=>{const v=latestRecords.find(v=>v.branch_id===$('#verifyBranch').value&&v.medication_id===$('#verifyMed').value);$('#verifyAvailability').value=v?.availability||'available';$('#verifyAvailability').onchange({target:$('#verifyAvailability')});$('#verifyQuantity').value=v&&v.quantity!==null&&v.availability==='available'?v.quantity:'';$('#verifyCommercial').value=v?.commercial||''};const medChanged=$('#verifyMed').onchange;$('#verifyMed').onchange=()=>{medChanged();fillCurrent()};$('#verifyBranch').onchange=fillCurrent;fillCurrent();$('#verifyForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),availability=f.get('availability'),dt=new Date(f.get('checked_at'));if(!Number.isFinite(dt.getTime())||dt.getTime()>Date.now()+60000){$('#formError').textContent='Revisa la fecha: no puede estar en el futuro.';return}const qty=availability==='out'?0:availability==='unknown'||!f.get('quantity')?null:Number(f.get('quantity'));if(qty!==null&&(!Number.isInteger(qty)||qty<0||qty>1000000)){ $('#formError').textContent='Usa una cantidad entera válida.';return}const v={id:crypto.randomUUID(),branch_id:f.get('branch_id'),medication_id:f.get('medication_id'),quantity:qty,availability,commercial:f.get('commercial').trim(),channel:f.get('channel'),checked_at:dt.toISOString(),verifier:f.get('verifier').trim(),notes:f.get('notes').trim(),created_at:new Date().toISOString()};if(!v.verifier||!branch(v.branch_id)||!med(v.medication_id)){ $('#formError').textContent='Completa los campos obligatorios.';return}if(await save({...data,verifications:[...data.verifications,v]})){ $('#dialog').close();refresh();toast('Verificación guardada. El seguimiento se actualizó.')}}}
function details(id){const b=branch(id);if(!b)return;const rows=latestRecords.filter(v=>v.branch_id===id);const phone=(b.phone||'').replace(/\D/g,'');modal(modalHead(esc(b.name),`${esc(b.id)} · ${esc(b.chain)} · ${esc(b.status)}`)+`<div class="detailgrid"><div><small>DIRECCIÓN</small><p>${esc(b.address)}</p></div><div><small>TERRITORIO</small><p>${esc(b.district||'Distrito no informado')}<br>${esc(b.municipality)} · ${esc(b.department)}</p></div><div><small>TELÉFONO</small><p>${esc(b.phone||'No informado')}</p></div><div><small>HORARIOS</small><p>L–V: ${esc(b.weekdays)}<br>Sábado: ${esc(b.saturday)}<br>Domingo: ${esc(b.sunday)}</p></div></div><div class="importexport">${phone.length===8?`<a class="btn secondary" href="tel:+503${phone}">Llamar ↗</a><a class="btn secondary" href="https://wa.me/503${phone}" target="_blank" rel="noopener">WhatsApp ↗</a>`:''}${b.lat&&b.lng?`<a class="btn secondary" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${b.lat},${b.lng}">Cómo llegar ↗</a>`:''}</div><p class="hint">El número proviene del directorio; no se ha confirmado si admite WhatsApp.</p><h3 class="smallheading">ÚLTIMAS VERIFICACIONES POR MEDICAMENTO</h3>${rows.length?rows.map(v=>`<div class="historyitem">${badge(status(v,data.settings))}<p><strong>${esc(med(v.medication_id)?.name)}</strong></p><p>${esc(quantity(v))} · ${esc(v.commercial||'Presentación no informada')}<br>${esc(fmt(v.checked_at,true))} · ${esc(v.channel)} · ${esc(v.verifier)}<br>${esc(v.notes)}</p></div>`).join(''):'<div class="dialoginfo">Sin existencias verificadas. No se infiere disponibilidad por aparecer en el directorio.</div>'}<div class="formactions"><button class="btn primary" id="verifyFromDetails">＋ Registrar verificación</button></div>`);$('#verifyFromDetails').onclick=()=>{$('#dialog').close();verify(id)}}
function addMedication(collection='unclassified'){if(collection==='isbm'&&!IsbmAccess.isUnlocked()){changeView('isbm');return}modal(modalHead('Agregar medicamento',collection==='isbm'?'Se agregará exclusivamente a Medicamentos ISBM.':'Se agregará al catálogo seleccionado, separado de ISBM.')+`<form id="medForm"><div class="formgrid"><label class="field full">Apartado<select name="collection" required>${[['isbm','Medicamentos ISBM'],['phase1','Primera fase'],['phase2','Segunda fase'],['unclassified','Sin clasificar']].filter(([k])=>k!=='isbm'||IsbmAccess.isUnlocked()).map(([k,label])=>`<option value="${k}" ${collection===k?'selected':''}>${label}</option>`).join('')}</select></label><label class="field full">Nombre genérico<input name="name" required maxlength="500"></label><label class="field">Composición / concentración<input name="composition" required maxlength="300"></label><label class="field">Tipo farmacéutico<input name="type" maxlength="200" required></label><label class="field full">Presentación del catálogo<input name="presentation" maxlength="500" required></label><label class="field full">Unidad de medida<input name="unit" required maxlength="100" placeholder="TABLETA, FRASCO, TUBO…"></label></div><div class="formactions"><button class="btn primary" type="submit">Agregar al catálogo</button></div></form>`);$('#medForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));for(const k of Object.keys(f))f[k]=f[k].trim();if(!f.name||!f.presentation||!f.unit||!f.composition||!f.type)return;const m={...f,id:crypto.randomUUID()};if(await save({...data,medications:[...data.medications,m]})){ $('#dialog').close();refresh();toast('Medicamento agregado al catálogo.')}}}
function renderSettings(){const r=data.settings;$('#settings').innerHTML=`<form class="panel formpanel" id="rulesForm"><h2>Reglas del semáforo</h2><p>Los días se cuentan por fecha de calendario en El Salvador. El seguimiento se recalcula al abrir la página y cada minuto. No mide ventas ni inventario en tiempo real.</p><div class="formgrid"><label class="field">Pocas existencias: hasta<input type="number" name="low" min="1" max="364" value="${r.low}" required><small>Unidades en la U/M del catálogo. Revisión inmediata.</small></label><label class="field">Existencias altas: desde<input type="number" name="high" min="2" max="365" value="${r.high}" required><small>Las cantidades entre ambos umbrales usan el plazo normal.</small></label></div><div class="rulegrid"><div class="rulebox"><h3>Existencias normales o cantidad no informada</h3><label class="field">Aviso amarillo a los días<input type="number" name="normalWarn" min="1" max="365" value="${r.normalWarn}" required></label><label class="field">Urgente rojo a los días<input type="number" name="normalDue" min="1" max="365" value="${r.normalDue}" required></label></div><div class="rulebox"><h3>Existencias altas</h3><label class="field">Aviso amarillo a los días<input type="number" name="highWarn" min="1" max="365" value="${r.highWarn}" required></label><label class="field">Urgente rojo a los días<input type="number" name="highDue" min="1" max="365" value="${r.highDue}" required></label></div><div class="rulebox"><h3>Pocas unidades</h3><p>Amarillo desde el registro para volver a confirmar.</p><label class="field">Urgente rojo a los días<input type="number" name="lowDue" min="1" max="365" value="${r.lowDue}" required></label></div><div class="rulebox"><h3>Sin existencias</h3><label class="field">Aviso amarillo a los días<input type="number" name="outWarn" min="1" max="365" value="${r.outWarn}" required></label><label class="field">Urgente rojo a los días<input type="number" name="outDue" min="1" max="365" value="${r.outDue}" required></label></div></div><p class="hint">Ejemplo con reglas iniciales: consulta el lunes → normal: amarillo miércoles, rojo jueves; altas: amarillo jueves, rojo viernes. Si no se confirma disponibilidad, entra en revisión inmediata.</p><p class="error" id="rulesError" role="alert"></p><div class="formactions"><button type="button" class="btn secondary" id="defaultRules">Restablecer reglas</button><button class="btn primary" type="submit">Guardar reglas</button></div></form><section class="panel formpanel"><h2>Respaldo y portabilidad</h2><p>${sharedView?'Estás trabajando con la base compartida. Todas las personas que abren la página ven los cambios confirmados.':'La conexión compartida aún no está disponible. Los registros locales se conservan.'} Los originales locales se conservan; exporta respaldos con frecuencia.</p><div class="importexport"><button class="btn secondary" id="exportBackup">↓ Exportar respaldo JSON</button><button class="btn secondary" id="importBackup">↑ Importar respaldo JSON</button><button class="btn secondary" id="csvSettings">↓ Exportar historial CSV</button></div><p class="hint">La importación combina el historial por identificador, incorpora medicamentos adicionales y conserva tus reglas actuales. Los archivos de respaldo contienen los nombres y notas que registraste.</p></section>`;if(FarmaSync.isTeamSession()&&FarmaSync.state().role!=='admin')$('#rulesForm').querySelectorAll('input,button').forEach(el=>el.disabled=true);$('#rulesForm').onsubmit=async e=>{e.preventDefault();const r=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,Number(v)]));if(!validRules(r)){ $('#rulesError').textContent='Usa enteros de 1 a 365. El umbral alto debe superar al bajo, y cada plazo urgente debe superar al de aviso.';return}if(await save({...data,settings:r})){refresh();toast('Reglas guardadas y seguimiento recalculado.')}};$('#defaultRules').onclick=async()=>{if(await save({...data,settings:{...defaults}})){refresh();toast('Reglas iniciales restablecidas.')}};$('#exportBackup').onclick=backup;$('#importBackup').onclick=()=>$('#importFile').click();$('#csvSettings').onclick=exportCsv}
function validRules(r){return Object.keys(defaults).every(k=>Number.isInteger(r[k])&&r[k]>=1&&r[k]<=365)&&r.high>r.low&&r.normalDue>r.normalWarn&&r.highDue>r.highWarn&&r.outDue>r.outWarn}
function download(text,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function backup(){download(JSON.stringify({...data,exported_at:new Date().toISOString()},null,2),'farmanexo-respaldo-'+new Date().toISOString().slice(0,10)+'.json','application/json');toast('Respaldo exportado. Guárdalo en un lugar seguro.')}
function exportCsv(){const header=['Sucursal','Codigo sucursal','Departamento','Codigo medicamento','Medicamento','Presentacion catalogo','Presentacion comercial','Disponibilidad','Cantidad','Unidad','Canal','Fecha ISO','Verificado por','Notas','Seguimiento actual del registro'];const rows=data.verifications.map(v=>{const b=branch(v.branch_id),m=med(v.medication_id);return [b?.name,v.branch_id,b?.department,m?.code||m?.id,m?.name,m?.presentation,v.commercial,stock(v),v.quantity,m?.unit,v.channel,v.checked_at,v.verifier,v.notes,status(v,data.settings).label]});const cell=x=>'"'+String(x??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';download('\uFEFF'+[header,...rows].map(r=>r.map(cell).join(',')).join('\r\n'),'farmanexo-verificaciones.csv','text/csv;charset=utf-8');toast(`${rows.length} verificaciones exportadas.`)}
function validData(o){if(!o||o.version!==1||!Array.isArray(o.verifications)||!Array.isArray(o.medications)||o.verifications.length>100000||o.medications.length>5000||!validRules(o.settings))return false;const ids=allKnownMedicationIds();for(const m of o.medications){if(!m||(m.collection!==undefined&&!['isbm','phase1','phase2','unclassified'].includes(m.collection))||typeof m.id!=='string'||ids.has(m.id)||!['name','presentation','composition','type','unit'].every(k=>typeof m[k]==='string'&&m[k].length>0&&m[k].length<=2000))return false;ids.add(m.id)}const recordIds=new Set();for(const v of o.verifications){if(!v||typeof v.id!=='string'||recordIds.has(v.id)||!branch(v.branch_id)||!ids.has(v.medication_id)||!['available','out','unknown'].includes(v.availability)||!['Llamada','WhatsApp','NERD','Otro'].includes(v.channel)||!Number.isFinite(Date.parse(v.checked_at))||Date.parse(v.checked_at)>Date.now()+60000||!Number.isFinite(Date.parse(v.created_at))||!(v.quantity===null||Number.isInteger(v.quantity)&&v.quantity>=0&&v.quantity<=1000000)||!['verifier','commercial','notes'].every(k=>typeof v[k]==='string'&&v[k].length<=3000)||!v.verifier.trim()||v.availability==='available'&&(v.quantity===0||!v.commercial.trim())||v.availability==='out'&&v.quantity!==0||v.availability==='unknown'&&v.quantity!==null)return false;recordIds.add(v.id)}return true}
async function importBackup(file){if(!file)return;try{if(file.size>25*1024*1024)throw Error();const o=JSON.parse(await file.text());if(!validData(o))throw Error();const merge=(a,b)=>[...new Map([...a,...b].map(x=>[x.id,x])).values()];const combined={...data,medications:merge(o.medications,data.medications),verifications:merge(o.verifications,data.verifications)};if(!validData(combined))throw Error();if(await save(combined)){refresh();toast(`Respaldo combinado: ${combined.verifications.length} verificaciones en total.`)}}catch{toast('Archivo no válido. Usa un respaldo JSON exportado desde FarmaNexo.')}$('#importFile').value=''}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-view],[data-detail],[data-verify]');if(!btn)return;if(btn.dataset.view)changeView(btn.dataset.view);else if(btn.dataset.detail)details(btn.dataset.detail);else if(btn.dataset.verify){if($('#dialog').open)$('#dialog').close();verify(btn.dataset.verify,btn.dataset.med||'')}});
async function init(){try{const result=await Promise.all([fetch('branches.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('catalog.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('isbm-index.json').then(r=>{if(!r.ok)throw Error();return r.json()})]);[branches,catalog,isbmIndex]=result;try{const raw=localStorage.getItem(KEY);if(raw){const o=JSON.parse(raw);if(validData(o))data=o;else toast('El respaldo local no es válido. No se sobrescribirá hasta que guardes nuevos datos.')}}catch{toast('No se pudo leer el almacenamiento local. Revisa los permisos del navegador.')}$('#today').textContent=new Intl.DateTimeFormat('es-SV',{day:'numeric',month:'long',year:'numeric',timeZone:'America/El_Salvador'}).format(new Date());$('#teamButton').onclick=openTeam;$('#lockIsbm').onclick=lockIsbm;$('#newVerification').onclick=()=>verify();$('#exportCsv').onclick=exportCsv;$('#backupSide').onclick=backup;$('#showRules').onclick=()=>changeView('settings');$('#dismissNotice').onclick=()=>{$('#notice').hidden=true;try{sessionStorage.setItem('notice-dismissed','1')}catch{}};$('#fitMap').onclick=()=>{const rows=renderMap.points;if(rows?.length)map.fitBounds(rows.map(b=>[b.lat,b.lng]),{padding:[25,25],maxZoom:13})};$('#importFile').onchange=e=>importBackup(e.target.files[0]);refresh();FarmaSync.init(syncData,syncState);setInterval(()=>{if(!$('#dialog').open)refresh()},60000);window.addEventListener('storage',e=>{if(e.key===KEY&&!FarmaSync.isTeamSession()){try{const o=JSON.parse(e.newValue);if(validData(o)){data=o;refresh();toast('Datos actualizados desde otra pestaña.')}}catch{}}})}catch(e){$('#notice').innerHTML='<p>No se pudo cargar el directorio. Recarga la página para volver a intentarlo.</p>';console.error(e)}}
init();
